"use strict";(globalThis.webpackChunkgrc||=[]).push([[49916],{62583(e){e.exports=JSON.parse('{"citeKey":"cernuda2024hades","slug":"cernuda-2024-hades-e18c","title":"Hades: A Context-Aware Active Storage Framework for Accelerating Large-Scale Data Analysis","authors":["J. Cernuda","L. Logan","A. Gainaru","J. Lofstead","A. Kougkas","X.-H. Sun"],"venue":"The 24th IEEE/ACM international Symposium on Cluster, Cloud and Internet Computing (CCGRID 2024)","type":"Conference","entryType":"inproceedings","date":"May, 2024","year":2024,"era":"iit","month":5,"doi":"10.1109/ccgrid59990.2024.00070","abstract":"Modern simulation workflows generate and analyze massive amounts of data using I/O libraries like Adios2 and NetCDF. Although extensive work has optimized the I/O processes during the simulation phase, executing analytical queries-which often require iterative traversals of large files for insights-is cumbersome and usually constrained by low I/O performance. Instead of waiting for the analysis phase to process queries, quantities can be derived asynchronously during data production and cached, speeding up future queries. In this work, we introduce a context-aware I/O layer named \'Hades.\' It is designed to efficiently derive insights from selected quantities without compromising overall workflow performance. Hades actively and asynchronously computes and stores these quantities while the data is in transit. Hades leverages a hierarchical buffering system with data access-aware prefetching to ensure quick and timely access to relevant data. It offers a flexible query interface empowering users to easily define derived quantities and provide control over data placement decisions. Hades is implemented using an Adios2 plugin engine and the Hermes buffering platform, enabling transparent use by any Adios-powered application or workflow. Experimental results demonstrate performance improvements by up to 3-4x for tested real-world scientific producer-consumer workflows. Index Terms-Active Storage, Hierarchical Storage, Context Awareness, Metadata Management, Data Operator, In-transit Computing","hasAbstract":true,"lede":"We introduce a context-aware I/O layer named \'Hades.\'","links":{"pdf":"https://grc.iit.edu/papers/2024/cernuda-2024-hades-e18c.pdf"},"tags":["Active Storage","Hierarchical Storage","Context Awareness","Metadata Management","Data Operator","In-Transit Computing","Coeus"],"_projectIds":["coeus"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["coeus"],"memberAuthors":["cernuda-jaime","logan-luke","gainaru-ana","lofstead-jay","kougkas-anthony","sun-xian-he"],"funding":[{"agency":"DOE","award":"DE-SC0023263","projectId":"coeus"}]}')}}]);